<?php
declare(strict_types=1);
require_once __DIR__.'/../../lib/helpers.php';require_once __DIR__.'/../../lib/admin.php';require_once __DIR__.'/../../lib/crypto.php';
send_cors_headers();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$token=(string)($body['challenge_token']??'');$code=preg_replace('/\D+/','',(string)($body['code']??''));if($token===''||strlen($code)!==6)json_response(422,['success'=>false,'message'=>'Enter the six-digit authentication code.']);
$db=get_db();$stmt=$db->prepare('SELECT c.*,a.mfa_secret_encrypted,a.status FROM admin_mfa_challenges c JOIN admin_users a ON a.id=c.admin_id WHERE c.token_hash=:hash AND c.used_at IS NULL AND c.expires_at>UTC_TIMESTAMP() LIMIT 1');$stmt->execute(['hash'=>session_hash($token)]);$challenge=$stmt->fetch();if(!$challenge||(int)$challenge['attempts']>=5)json_response(401,['success'=>false,'message'=>'The authentication challenge is invalid or expired.']);
if(!verify_totp(decrypt_sensitive($challenge['mfa_secret_encrypted']),$code)){$db->prepare('UPDATE admin_mfa_challenges SET attempts=attempts+1 WHERE id=:id')->execute(['id'=>$challenge['id']]);json_response(401,['success'=>false,'message'=>'The authentication code is incorrect.']);}
$db->beginTransaction();try{$db->prepare('UPDATE admin_mfa_challenges SET used_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$challenge['id']]);$db->prepare('UPDATE admin_users SET last_login_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$challenge['admin_id']]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}$session=create_auth_session('admin',$challenge['admin_id'],false);audit_event('admin.login_mfa','admin',$challenge['admin_id'],[],['type'=>'admin','id'=>$challenge['admin_id']]);json_response(200,['success'=>true,'csrf_token'=>$session['csrf_token'],'redirect'=>'../index.php']);
